type Request = {
  // 消息或 prompt（二选一）
  messages?: Message[];
  prompt?: string;

  // 模型选择
  model?: string;              // 如 "openai/gpt-5.2"
  models?: string[];           // Model Fallback
  route?: 'fallback';          // 启用 Fallback 路由

  // 输出格式控制
  response_format?: ResponseFormat;
  stop?: string | string[];
  stream?: boolean;            // 启用 SSE 流式

  // 插件
  plugins?: Plugin[];

  // 采样参数
  max_tokens?: number;         // [1, context_length)
  temperature?: number;        // [0, 2]，默认 1.0
  top_p?: number;              // (0, 1]，默认 1.0
  top_k?: number;              // [1, ∞)
  frequency_penalty?: number;  // [-2, 2]，默认 0
  presence_penalty?: number;   // [-2, 2]，默认 0
  repetition_penalty?: number; // (0, 2]，默认 1.0
  min_p?: number;              // [0, 1]
  top_a?: number;              // [0, 1]
  seed?: number;               // 整数
  logit_bias?: Record<number, number>;
  logprobs?: boolean;
  top_logprobs?: number;       // [0, 20]

  // Tool Calling
  tools?: Tool[];
  tool_choice?: ToolChoice;
  parallel_tool_calls?: boolean; // 默认 true

  // Verbosity 控制（OpenAI/Anthropic）
  verbosity?: 'low' | 'medium' | 'high' | 'max';

  // 预测输出（延迟优化）
  prediction?: { type: 'content'; content: string };

  // OpenRouter 专属
  provider?: ProviderPreferences;
  user?: string;               // 终端用户标识（滥用检测）

  // 调试选项（仅 Streaming）
  debug?: {
    echo_upstream_body?: boolean; // 返回发送给 Provider 的请求体
  };
};

type Message =
  | {
      role: 'user' | 'assistant' | 'system';
      content: string | ContentPart[];
      name?: string;
    }
  | {
      role: 'tool';
      content: string;
      tool_call_id: string;
      name?: string;
    };

type ContentPart = TextContent | ImageContentPart;

type TextContent = {
  type: 'text';
  text: string;
};

type ImageContentPart = {
  type: 'image_url';
  image_url: {
    url: string;    // URL 或 Base64 编码
    detail?: string; // 默认 "auto"
  };
};

type Response = {
  id: string;
  choices: NonStreamingChoice[];
  created: number;             // Unix 时间戳
  model: string;               // 实际使用的模型
  object: 'chat.completion';
  system_fingerprint?: string;
  usage?: ResponseUsage;
};

type NonStreamingChoice = {
  message: {
    role: 'assistant';
    content: string | null;
    tool_calls?: ToolCall[];
  };
  finish_reason: string;       // "stop" | "length" | "tool_calls" | "error"
  index: number;
};

type ResponseUsage = {
  prompt_tokens: number;
  completion_tokens: number;
  total_tokens: number;
  prompt_tokens_details?: {
    cached_tokens: number;      // 缓存命中 token 数
    cache_write_tokens: number; // 缓存写入 token 数
  };
};

type StreamChunk = {
  id: string;
  choices: StreamingChoice[];
  created: number;
  model: string;
  object: 'chat.completion.chunk';
  usage?: ResponseUsage;       // 仅最后一个 chunk 包含
};

type StreamingChoice = {
  delta: {
    role?: 'assistant';
    content?: string;
    tool_calls?: ToolCallDelta[];
  };
  finish_reason: string | null;
  index: number;
};

type Tool = {
  type: 'function';
  function: {
    name: string;
    description?: string;
    parameters: object;  // JSON Schema
  };
};

type ToolChoice =
  | 'none'     // 不调用任何工具
  | 'auto'     // 模型自行决定
  | 'required' // 必须调用工具
  | { type: 'function'; function: { name: string } }; // 指定工具

{
  "model": "openai/gpt-5.2",
  "messages": [
    { "role": "user", "content": "What's the weather in London?" }
  ],
  "tools": [
    {
      "type": "function",
      "function": {
        "name": "get_weather",
        "description": "Get current weather for a location",
        "parameters": {
          "type": "object",
          "properties": {
            "location": { "type": "string" }
          },
          "required": ["location"]
        }
      }
    }
  ],
  "tool_choice": "auto"
}

{
  "model": "openai/gpt-5.2",
  "messages": [
    { "role": "user", "content": "What is the meaning of life?" },
    { "role": "assistant", "content": "I'm not sure, but my best guess is" }
  ]
}
